import {scenarioAllowsBackground} from './scenario-background-rules.js?v=ordinance-comparison-1';
import {recordHazard} from './emergency-order.js?v=ordinance-comparison-1';
import {beginEmergencySession} from './emergency-session.js?v=ordinance-comparison-1';
const food=t=>t.nature||t.type==='industrial'&&t.industry==='farm'&&t.level>0;
export const freshLocusts=()=>({randomLocusts:false,locust:null,cropDusters:[],nextDuster:0,locustPlagues:0,vegetationLost:0});
export function startLocusts(c,x,y){const n=Math.sqrt(c.tiles.length),e=c.emergency;if(e.locust)return{ok:false,error:'This disaster type is already active.'};if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=n||y>=n)return{ok:false,error:'Choose a tile inside the city.'};if(!c.tiles.some(food))return{ok:false,error:'There are no trees or farm crops for locusts to eat.'};beginEmergencySession(c);recordHazard(e,'locust');Object.assign(e,{locust:{x,y,age:0,strength:100},cropDusters:[],nextDuster:0});e.locustPlagues++;return{ok:true};}
export function dispatchCropDuster(c,x,y){const e=c.emergency,n=Math.sqrt(c.tiles.length);if(!e.locust)return{ok:false,error:'Crop dusters are available during a locust plague.'};if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=n||y>=n||c.tiles[y*n+x].terrain==='water')return{ok:false,error:'Choose land for the crop dusters to spray.'};const unit={x,y,delay:2,remaining:10},idle=e.cropDusters.findIndex(d=>d.remaining===0);if(idle>=0)e.cropDusters[idle]=unit;else if(e.cropDusters.length<3)e.cropDusters.push(unit);else{e.cropDusters[e.nextDuster%3]=unit;e.nextDuster=(e.nextDuster+1)%3;}return{ok:true};}
export function stepLocusts(c){const e=c.emergency,s=e.locust;if(!s)return 0;s.age++;let lost=0;
 for(const d of e.cropDusters){if(d.delay>0)d.delay--;else if(d.remaining>0)d.remaining--;}
 const sprayed=()=>e.cropDusters.some(d=>!d.delay&&d.remaining>0&&Math.hypot(d.x-s.x,d.y-s.y)<=4);
 if(sprayed())s.strength=Math.max(0,s.strength-30);
 if(s.strength>0){const targets=c.tiles.filter(food).sort((a,b)=>Math.hypot(a.x-s.x,a.y-s.y)-Math.hypot(b.x-s.x,b.y-s.y));const target=targets[0];if(target){if(Math.abs(target.x-s.x)>=Math.abs(target.y-s.y))s.x+=Math.sign(target.x-s.x);else s.y+=Math.sign(target.y-s.y);
 // Sprayed vegetation poisons arriving swarms before they feed.
 if(sprayed())s.strength=Math.max(0,s.strength-30);
 if(s.strength>0)for(const t of c.tiles){if(!food(t)||Math.hypot(t.x-s.x,t.y-s.y)>1.5)continue;if(t.nature){t.nature=false;t.treeLevel=0;lost++;}if(t.industry==='farm'){const root=t.farmRoot;for(const u of c.tiles)if(u.industry==='farm'&&u.farmRoot===root){u.level=0;u.abandonedLevel=0;u.age=0;u.stress=0;u.industry='dirty';u.farmRoot=null;lost++;}}}
 }else s.strength=0;}
 e.vegetationLost+=lost;if(s.strength<=0||s.age>=36){e.locust=null;e.cropDusters=[];e.nextDuster=0;}return lost;
}
export function validateLocusts(v,n,version){if(version<31)return freshLocusts();if(version>=32&&typeof v.randomLocusts!=='boolean')throw Error('Invalid random locust setting.');const coord=p=>p&&Number.isInteger(p.x)&&Number.isInteger(p.y)&&p.x>=0&&p.y>=0&&p.x<n&&p.y<n;
 if(!Array.isArray(v.cropDusters)||v.cropDusters.length>3||!Number.isInteger(v.nextDuster)||v.nextDuster<0||v.nextDuster>2||['locustPlagues','vegetationLost'].some(k=>!Number.isInteger(v[k])||v[k]<0||v[k]>1e9))throw Error('Invalid locust data.');
 let locust=null;if(v.locust!==null){const s=v.locust;if(!coord(s)||!v.active||(version<96&&(v.earthquake||v.tornado))||!v.locustPlagues||!Number.isInteger(s.age)||s.age<0||s.age>=36||!Number.isInteger(s.strength)||s.strength<=0||s.strength>100)throw Error('Invalid locust swarm.');locust={x:s.x,y:s.y,age:s.age,strength:s.strength};}
 if(!locust&&v.cropDusters.length)throw Error('Crop dusters require an active swarm.');const cropDusters=v.cropDusters.map(d=>{if(!coord(d)||!Number.isInteger(d.delay)||d.delay<0||d.delay>2||!Number.isInteger(d.remaining)||d.remaining<0||d.remaining>10)throw Error('Invalid crop duster.');return{x:d.x,y:d.y,delay:d.delay,remaining:d.remaining};});return{randomLocusts:version>=32?v.randomLocusts:false,locust,cropDusters,nextDuster:v.nextDuster,locustPlagues:v.locustPlagues,vegetationLost:v.vegetationLost};}

export function setRandomLocusts(c,value){if(c.emergency.active)return{ok:false,error:'Finish the active disaster before changing random outbreaks.'};if(typeof value!=='boolean')return{ok:false,error:'Choose a valid disaster setting.'};c.emergency.randomLocusts=value;return{ok:true};}
export function locustRisk(c){if(!c.tiles.some(food))return 0;const farms=c.tiles.filter(t=>t.industry==='farm'&&t.farmRoot===t.y*Math.sqrt(c.tiles.length)+t.x).length;return Math.min(.015,.003+farms*.0005);}
const roll=(month,seed,salt)=>{let n=Math.imul(month+salt,374761393)^Math.imul(seed+17,668265263);n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967296;};
export function maybeLocusts(c){if(!scenarioAllowsBackground(c,'randomDisasters'))return false;if(!c.emergency.randomLocusts||c.emergency.active||roll(c.month,c.seed,701)>=locustRisk(c))return false;const n=Math.sqrt(c.tiles.length),position=Math.floor(roll(c.month,c.seed,709)*n),edge=Math.floor(roll(c.month,c.seed,719)*4),[x,y]=[[0,position],[n-1,position],[position,0],[position,n-1]][edge];return startLocusts(c,x,y).ok;}
export function cropDusterReport(c){const rows=c.emergency.cropDusters;return `<div class="table-scroll"><table><thead><tr><th>Plane</th><th>Status</th><th>Assignment</th></tr></thead><tbody>${[0,1,2].map(i=>{const d=rows[i];return `<tr><td>${i+1}</td><td>${!d||!d.remaining?'Ready for dispatch':d.delay?'En route · '+d.delay+' steps':'Spraying · '+d.remaining+' steps left'}</td><td>${d?(d.x+1)+', '+(d.y+1):'Unassigned'}</td></tr>`;}).join('')}</tbody></table></div><p>New orders reuse a ready plane first. When all three are busy, orders replace assignments in rotation.</p>`;}
